import 'package:flutter/material.dart';\nimport '../../config/theme/app_theme.dart';\nimport '../../services/ai_survival_assistant.dart';\n\nclass AIAssistantScreen extends StatefulWidget {\n  const AIAssistantScreen({Key? key}) : super(key: key);\n\n  @override\n  State<AIAssistantScreen> createState() => _AIAssistantScreenState();\n}\n\nclass _AIAssistantScreenState extends State<AIAssistantScreen> {\n  final AISurvivalAssistant _aiAssistant = AISurvivalAssistant();\n  final TextEditingController _queryController = TextEditingController();\n  List<Map<String, String>> _messages = [];\n\n  void _sendQuery() async {\n    if (_queryController.text.isEmpty) return;\n\n    final query = _queryController.text;\n    _queryController.clear();\n\n    setState(() {\n      _messages.add({'type': 'user', 'text': query});\n    });\n\n    String response = 'Processing your query...';\n    \n    if (query.toLowerCase().contains('terrain')) {\n      response = 'Analyzing terrain... Medium risk detected. Recommended safe route available.';\n    } else if (query.toLowerCase().contains('battery')) {\n      response = 'Battery optimization active. Estimated survival time: 6 hours at current usage.';\n    } else if (query.toLowerCase().contains('water')) {\n      response = 'Nearest water source: 2.3 km northeast. Caution: verify water safety before consumption.';\n    } else if (query.toLowerCase().contains('lost')) {\n      response = 'Activating return path system. Safe route reconstructed. Follow breadcrumb trail backward.';\n    } else {\n      response = 'AI Assistant: Processing complete. No immediate threats detected.';\n    }\n\n    setState(() {\n      _messages.add({'type': 'ai', 'text': response});\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('AI Survival Assistant'),\n        backgroundColor: AppTheme.backgroundColor,\n      ),\n      backgroundColor: AppTheme.backgroundColor,\n      body: Column(\n        children: [\n          Expanded(\n            child: ListView.builder(\n              itemCount: _messages.length,\n              itemBuilder: (context, index) {\n                final message = _messages[index];\n                final isUser = message['type'] == 'user';\n                return Align(\n                  alignment: isUser ? Alignment.centerRight : Alignment.centerLeft,\n                  child: Container(\n                    margin: const EdgeInsets.all(8),\n                    padding: const EdgeInsets.all(12),\n                    decoration: BoxDecoration(\n                      color: isUser ? AppTheme.primaryColor : AppTheme.surfaceColor,\n                      borderRadius: BorderRadius.circular(8),\n                    ),\n                    child: Text(\n                      message['text']!,\n                      style: TextStyle(\n                        color: isUser ? AppTheme.backgroundColor : AppTheme.textSecondary,\n                      ),\n                    ),\n                  ),\n                );\n              },\n            ),\n          ),\n          Padding(\n            padding: const EdgeInsets.all(16),\n            child: Row(\n              children: [\n                Expanded(\n                  child: TextField(\n                    controller: _queryController,\n                    style: const TextStyle(color: AppTheme.textPrimary),\n                    decoration: InputDecoration(\n                      hintText: 'Ask ANIS...',\n                      hintStyle: const TextStyle(color: AppTheme.textTertiary),\n                      filled: true,\n                      fillColor: AppTheme.surfaceColor,\n                      border: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(8),\n                        borderSide: const BorderSide(color: AppTheme.primaryColor),\n                      ),\n                    ),\n                  ),\n                ),\n                const SizedBox(width: 8),\n                ElevatedButton(\n                  onPressed: _sendQuery,\n                  style: ElevatedButton.styleFrom(\n                    backgroundColor: AppTheme.primaryColor,\n                  ),\n                  child: const Icon(Icons.send),\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n